"""Standalone interactive review of all stage-one test reconstructions."""
import argparse,json
from pathlib import Path
import numpy as np
from representation import decode_path
ROOT=Path(__file__).resolve().parents[2]
def main():
    ap=argparse.ArgumentParser();ap.add_argument('--out',type=Path,default=ROOT/'reports/transformer_stage1_20261012');a=ap.parse_args();out=a.out;z=np.load(out/'dataset.npz');run=json.loads((out/'remote/run.json').read_text());actual=np.exp(z['test_target_log']);base=np.exp(z['test_anchor_log'][:,2]);models={};errors={}
    for kind in ['static','hyper','hyper_fixed']:
        p=np.load(out/'remote'/f'{kind}_test.npz')['angles'];path=np.exp(decode_path(p,z['test_anchor_log'],float(z['s15'])))
        models[kind]=np.round(path-base[:,None,None],6).tolist();errors[kind]=np.abs(path-actual).mean((1,2)).tolist()
    data=dict(selected=run['selected_family'],dates=[str(np.datetime64(int(z['start_minute']+i),'m')) for i in z['test_origins']],actual=np.round(actual-base[:,None,None],6).tolist(),models=models,errors=errors)
    page=r'''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Первый этап — проверка прошлого</title>
<style>body{font:16px system-ui;background:#f5f6f8;color:#182235;max-width:1160px;margin:28px auto;padding:0 18px}h1{font-size:27px;margin-bottom:10px}.card{background:white;padding:18px;border-radius:12px;margin:16px 0}label,button,select{margin-right:12px}button,select{padding:8px;border:1px solid #bec6d3;border-radius:6px;background:white;color:#182235}input{width:100%}canvas{width:100%;height:440px}.muted{color:#546175;line-height:1.5}table{border-collapse:collapse;width:100%;font-size:14px}td,th{padding:8px;border-bottom:1px solid #e5e9ee;text-align:right}th:first-child,td:first-child{text-align:left}#stats{font-weight:600;margin-top:14px}.legend span{display:inline-block;margin:10px 20px 0 0}.dot{display:inline-block;width:12px;height:12px;margin-right:5px}</style>
<h1>Первый этап: восстановление видимого прошлого</h1><p class="muted">Это последние 120 минут, уже находящиеся во входе модели. Будущее не предсказывается. Вход — угловые H/O/C/L-векторы и доступность данных; абсолютные цены используются только для отображения после модели.</p>
<div class="card"><label>Модель <select id="model"><option value="static">Transformer</option><option value="hyper">Transformer + гиперсеть</option><option value="hyper_fixed">Гиперсеть с фиксированным условием</option></select></label><button id="prev">←</button><button id="next">→</button><button id="worst">Худший пример</button><button id="typical">Средний по ошибке</button><p id="date"></p><input id="sample" type="range" min="0" step="1"><div id="stats"></div></div>
<div class="card"><canvas id="chart"></canvas><div class="legend"><span><i class="dot" style="background:#333"></i>Фактические свечи</span><span><i class="dot" style="background:#3266ad"></i>Восстановленные</span><span><i class="dot" style="background:#a624a6"></i>Неверная геометрия</span></div><p class="muted">Горизонтальная ось — минуты видимого прошлого. Вертикальная — доллары относительно Close свечи перед этим участком. Предсказанные цены не сортируются и не исправляются.</p></div>
<div class="card"><table><thead><tr><th>Участок прошлого</th><th>Close: факт</th><th>Close: модель</th><th>Ошибка OHLC</th><th>Геометрия</th></tr></thead><tbody id="rows"></tbody></table></div>
<script id="data" type="application/json">DATA_JSON</script><script>
const d=JSON.parse(document.getElementById('data').textContent),slider=document.getElementById('sample'),selector=document.getElementById('model');slider.max=d.dates.length-1;selector.value=d.selected;
function render(){const i=Number(slider.value),key=selector.value,a=d.actual[i],p=d.models[key][i],err=d.errors[key][i];let valid=0;for(const v of p)valid+=v[0]>=Math.max(v[1],v[2])&&v[3]<=Math.min(v[1],v[2]);document.getElementById('date').textContent=`${d.dates[i]} · пример ${i+1} / ${d.dates.length}`;document.getElementById('stats').textContent=`Средняя ошибка OHLC: $${err.toFixed(3)} · геометрически верны ${valid} / 8 свечей`;
const c=document.getElementById('chart'),ratio=window.devicePixelRatio||1,w=c.clientWidth,h=440;c.width=w*ratio;c.height=h*ratio;const ctx=c.getContext('2d');ctx.scale(ratio,ratio);ctx.clearRect(0,0,w,h);const left=65,right=22,top=25,bottom=52,all=[...a.flat(),...p.flat()],lo0=Math.min(...all),hi0=Math.max(...all),pad=Math.max((hi0-lo0)*.12,.12),lo=lo0-pad,hi=hi0+pad;const X=t=>left+(t/8)*(w-left-right),Y=v=>top+(hi-v)/(hi-lo)*(h-top-bottom);ctx.font='12px system-ui';ctx.strokeStyle='#e3e7ed';ctx.fillStyle='#546175';
for(let k=0;k<=5;k++){const v=lo+(hi-lo)*k/5,y=Y(v);ctx.beginPath();ctx.moveTo(left,y);ctx.lineTo(w-right,y);ctx.stroke();ctx.fillText(v.toFixed(2),8,y+4)}
for(let k=0;k<8;k++)ctx.fillText(String(-120+k*15),X(k)+8,h-28);ctx.fillText('минуты прошлого',w/2-52,h-7);ctx.fillText('$',15,15);
function draw(v,x,color){const good=v[0]>=Math.max(v[1],v[2])&&v[3]<=Math.min(v[1],v[2]);ctx.strokeStyle=good?color:'#a624a6';ctx.fillStyle=ctx.strokeStyle;ctx.globalAlpha=.75;ctx.beginPath();ctx.moveTo(x,Y(v[0]));ctx.lineTo(x,Y(v[3]));ctx.stroke();const width=Math.min(15,(w-left-right)/30);ctx.fillRect(x-width/2,Math.min(Y(v[1]),Y(v[2])),width,Math.max(1,Math.abs(Y(v[1])-Y(v[2]))));ctx.globalAlpha=1}
for(let k=0;k<8;k++){const x=X(k+.5);draw(a[k],x-9,'#333');draw(p[k],x+9,'#3266ad')}
const rows=document.getElementById('rows');rows.replaceChildren();for(let k=0;k<8;k++){let sum=0;for(let j=0;j<4;j++)sum+=Math.abs(a[k][j]-p[k][j]);const ok=p[k][0]>=Math.max(p[k][1],p[k][2])&&p[k][3]<=Math.min(p[k][1],p[k][2]);const tr=document.createElement('tr');for(const value of [`${-120+k*15} … ${-105+k*15} мин`,a[k][2].toFixed(3),p[k][2].toFixed(3),'$'+(sum/4).toFixed(3),ok?'Верна':'Неверна']){const td=document.createElement('td');td.textContent=value;tr.append(td)}rows.append(tr)}}
slider.addEventListener('input',render);selector.addEventListener('change',render);document.getElementById('prev').onclick=()=>{slider.value=Math.max(0,Number(slider.value)-1);render()};document.getElementById('next').onclick=()=>{slider.value=Math.min(d.dates.length-1,Number(slider.value)+1);render()};document.getElementById('worst').onclick=()=>{const es=d.errors[selector.value];slider.value=es.indexOf(Math.max(...es));render()};document.getElementById('typical').onclick=()=>{const es=d.errors[selector.value],order=es.map((e,i)=>[e,i]).sort((a,b)=>a[0]-b[0]);slider.value=order[Math.floor(order.length/2)][1];render()};window.addEventListener('resize',render);render();
</script></html>'''
    (out/'review.html').write_text(page.replace('DATA_JSON',json.dumps(data,separators=(',',':'))));print('Review:',out/'review.html','samples:',len(data['dates']))
if __name__=='__main__':main()
